@charset "UTF-8";
.cdk-visually-hidden {
  border: 0;
  clip: rect(0 0 0 0);
  height: 1px;
  margin: -1px;
  overflow: hidden;
  padding: 0;
  position: absolute;
  width: 1px;
  white-space: nowrap;
  outline: 0;
  -webkit-appearance: none;
  -moz-appearance: none;
  left: 0;
}
[dir="rtl"] .cdk-visually-hidden {
  left: auto;
  right: 0;
}
.branding .radio-input-spacing {
  align-items: flex-start;
}
.branding .radio-input-spacing:before {
  margin-block-start: var(--rems-6px);
}
.branding .radio-input-spacing > input,
.branding .radio-input-spacing .radio-input-flex {
  flex: 1 1 auto;
}
.branding-wording .radio-input-spacing {
  margin-inline-start: 2rem;
}
.branding-wording .drop-box.form-section {
  display: flex;
  justify-content: center;
  inline-size: 413px;
  block-size: 95px;
}
.entitle-check-grp {
  margin-block-start: 0;
  margin-block-end: 0;
}
.page-header {
  margin: 0;
  padding: 0;
}
.user-img {
  display: inline-block;
  vertical-align: middle;
  overflow: hidden;
  border-radius: 50%;
  background-color: var(--mch-Indicator-locked);
  background-image: none;
  background-size: cover;
  background-repeat: no-repeat;
  text-align: center;
}
.user-img .icon {
  color: var(--mch-InvertedTextPrimary-normal);
}
.grid-refresh {
  position: absolute;
  inset-block-start: 20rem;
  inset-inline-start: 50%;
}
@media screen {
  #printSection {
    display: none;
  }
}
.panel {
  border-radius: calc(var(--rems-14px) / 2);
  margin-block-start: var(--rems-30px);
  margin-block-end: var(--rems-30px);
}
[ng\:cloak],
[ng-cloak],
.ng-cloak {
  display: none;
}
.invalid {
  background-color: var(--mch-BackgroundSolidTertiary-normal) !important;
  color: var(--mch-TextSecondary-normal);
}
.invalid .md-close,
.invalid .md-close:hover {
  color: var(--mch-TextSecondary-normal);
}
.close {
  color: var(--mch-TextPrimary-normal);
  opacity: 0.7;
}
.close:hover {
  color: var(--mch-InvertedTextPrimary-normal);
  opacity: 1;
}
.nav > li:focus,
.nav > li:active,
.nav > li.active {
  z-index: 90;
}
.md-modal__title span {
  font-size: inherit;
}
.feature-list .status-icon {
  line-height: var(--rems-36px);
  margin-inline-end: var(--rems-10px);
}
.feature-list .status-indicator {
  line-height: var(--rems-36px);
}
.feature-list .feature-status span {
  font-size: 0.75rem;
}
.userStatusesExport-form {
  display: flex;
  margin-block-start: 1rem;
}
.userStatusesExport-form h5 {
  margin-block-end: var(--rems-10px);
}
.userStatusesExport-form > div {
  margin-inline-end: 5rem;
}
.export-user-statuses-progress-info {
  padding-block-end: 0.5rem;
}
.hercules-fix-paragraphs p {
  margin-block-end: 1rem;
}
label.toggle-switch {
  padding-block-start: 0 !important;
}
.hybrid-services-warning-message {
  position: relative;
  margin-block-start: 1rem;
}
.hybrid-services-warning-message .icon {
  position: absolute;
  color: var(--mch-TextWarning-normal);
  inset-block-start: var(--rems-3px);
}
.hybrid-services-message {
  font-size: var(--rems-14px);
  max-inline-size: 36rem;
  margin-inline-start: 1.5rem;
}
#webexSiteReports .md-ng1-card-container {
  padding-inline-end: 0;
  padding-inline-start: 0;
}
#webexSiteReports .md-ng1-card-container .md-ng1-card-layout {
  margin-block-end: 0;
}
.webexlogo {
  padding-inline-end: var(--rems-4px);
}
*,
*:after,
*:before {
  box-sizing: border-box;
}
html {
  line-height: 1.15;
  -webkit-text-size-adjust: 100%;
}
body {
  margin: 0;
  padding: 0;
  -moz-osx-font-smoothing: grayscale;
  -webkit-font-smoothing: antialiased;
  font-feature-settings: "liga";
  text-rendering: optimizeLegibility;
}
article,
aside,
details,
figcaption,
figure,
footer,
header,
main,
menu,
nav,
section {
  display: block;
}
output {
  display: inline-block;
}
summary {
  display: list-item;
}
hr {
  box-sizing: content-box;
  height: 0;
  overflow: visible;
}
blockquote,
dd,
dl,
dt,
form,
h1,
h2,
h3,
h4,
h5,
h6,
li,
ol,
p,
pre,
td,
th,
ul {
  font-weight: 400;
  margin: 0;
  padding: 0;
}
a {
  background-color: transparent;
}
abbr[title] {
  border-bottom: none;
  text-decoration: underline;
  text-decoration: underline dotted;
  text-decoration-skip-ink: none;
  cursor: help;
}
b,
strong {
  font-weight: bolder;
}
small {
  font-size: 80%;
}
sub,
sup {
  font-size: 75%;
  line-height: 0;
  position: relative;
  vertical-align: baseline;
}
sub {
  bottom: -0.25em;
}
sup {
  top: -0.5em;
}
code,
kbd,
pre,
samp {
  font-family: monospace, monospace;
  font-size: 1em;
}
img {
  border-style: none;
}
svg {
  overflow: hidden;
}
button,
input,
optgroup select,
textarea {
  font-family: inherit;
  font-size: 100%;
  line-height: 1.5;
  margin: 0;
}
button,
input {
  overflow: visible;
}
button,
select {
  text-transform: none;
}
select {
  word-wrap: normal;
}
button::-moz-focus-inner,
[type="button"]::-moz-focus-inner,
[type="reset"]::-moz-focus-inner,
[type="submit"]::-moz-focus-inner {
  border-style: none;
  padding: 0;
}
button:-moz-focusring,
[type="button"]:-moz-focusring,
[type="reset"]:-moz-focusring,
[type="submit"]:-moz-focusring {
  outline: 1px dotted ButtonText;
}
button:not(:disabled),
[type="button"]:not(:disabled),
[type="reset"]:not(:disabled),
[type="submit"]:not(:disabled) {
  cursor: pointer;
}
fieldset {
  padding: 0.35em 0.75em 0.625em;
}
legend {
  color: inherit;
  display: table;
  max-width: 100%;
  padding: 0;
  white-space: normal;
}
progress {
  vertical-align: baseline;
}
textarea {
  overflow: auto;
}
[type="checkbox"],
[type="radio"] {
  padding: 0;
}
input[type="time"],
input[type="datetime-local"],
input[type="month"] {
  -webkit-appearance: listbox;
}
[type="number"]::-webkit-inner-spin-button,
[type="number"]::-webkit-outer-spin-button {
  height: auto;
}
[type="search"] {
  -webkit-appearance: textfield;
  outline-offset: -2px;
}
[type="search"]::-webkit-search-decoration {
  -webkit-appearance: none;
}
::-webkit-file-upload-button {
  -webkit-appearance: button;
  font: inherit;
}
table {
  border-collapse: collapse;
}
[tabindex="-1"]:focus {
  outline: 0 !important;
}
template,
[hidden] {
  display: none;
}
