.p-datatable-thead,
.p-datatable-thead tr,
.p-datatable-thead th {
  position: relative;
  background: var(--mch-BackgroundSolidTertiary-normal);
}
.p-datatable-thead:hover,
.p-datatable-thead tr:hover,
.p-datatable-thead th:hover {
  background: var(--mch-BackgroundLabelDefault-hover);
  transition: background-color 0.2s;
}
.p-datatable-thead:active,
.p-datatable-thead tr:active,
.p-datatable-thead th:active {
  background: var(--mch-BackgroundLabelDefault-active);
}
.p-datatable-thead th input[type="text"] {
  padding: 0 0.75rem;
  border: var(--rems-1px) solid var(--mch-OutlineInput-normal);
  border-radius: 0.5rem;
  background-color: var(--mch-BackgroundSolidPrimary-normal);
  color: var(--mch-TextPrimary-normal);
  font-weight: var(--font-weight-regular);
  font-size: var(--rems-14px);
  block-size: 2rem;
}
.p-datatable-thead th input[type="text"]::placeholder {
  color: var(--mch-TextSecondary-normal);
}
.p-datatable-thead th input[type="text"]:hover {
  background-color: var(--mch-BackgroundPrimary-hover);
}
.p-datatable-thead th input[type="text"]:focus {
  background-color: var(--mch-BackgroundSolidPrimary-normal);
  box-shadow: var(--mch-Focus);
  outline: none;
}
.p-datatable-tbody tr {
  background-color: var(--mch-BackgroundSolidPrimary-normal);
}
.p-datatable-tbody tr td {
  box-shadow: inset 0 -1px 0 0 var(--mch-OutlineSecondary-normal);
}
.p-datatable-tbody tr.p-selectable-row {
  transition:
    background-color 0.2s,
